Request: headache log by time of day

The section must do:
- the figure "Morning": headaches logged before noon (the plan works it out as 0; for its example that is 0)
- the figure "Afternoon": headaches logged from noon to 6pm (the plan works it out as 0; for its example that is 0)
- the figure "Evening": headaches logged from 6pm to midnight (the plan works it out as 0; for its example that is 0)

The program already has these: use them, do not make your own:
- a list of entries: state.entries is LogEntry[] with the fields {when: number, severity: number, noteItem: string, minute: number}. Its form, its Add and Remove buttons and its rows are already on the screen. The section makes no list of its own for the same entries; to add one it copies state.entries into a new array, pushes a LogEntry (minute: time.hourOfDay() * 60 + time.minuteOfHour()) and returns {entries: thatArray __PASSTHROUGH__}.

Nothing they show is shown again: no second list, total, chart, Remove last or Start over button. While what the section works from is still empty, it shows one plain line saying what will appear and when, never a ui.EmptyState: the list above already has one (two empty states one under the other read as a broken screen).

The program so far, which the section joins (do not repeat it):
import * as ui from "std/ui"

@jsonable
class LogEntry {
  when: number;
  severity: number;
  noteItem: string;
  minute: number;
}

@jsonable
class AppState {
  entries: LogEntry[];
  draft_when: number;
  draft_severity: string;
  draft_noteItem: string;
  removedEntries: LogEntry[];
  removedAt: number;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {entries: emptyEntries, draft_when: 720, draft_severity: "", draft_noteItem: "", removedEntries: emptyEntries, removedAt: -1};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}







function set_draft_when(state: AppState, value: number): AppState {
  return {draft_when: value, entries: state.entries, draft_severity: state.draft_severity, draft_noteItem: state.draft_noteItem, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_draft_severity(state: AppState, value: string): AppState {
  return {draft_severity: value, entries: state.entries, draft_when: state.draft_when, draft_noteItem: state.draft_noteItem, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_draft_noteItem(state: AppState, value: string): AppState {
  return {draft_noteItem: value, entries: state.entries, draft_when: state.draft_when, draft_severity: state.draft_severity, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_noteItem) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {when: state.draft_when, severity: strings.toNumber(state.draft_severity, 0), noteItem: strings.trim(state.draft_noteItem), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_severity: "", draft_noteItem: "", draft_when: state.draft_when, removedAt: state.removedAt};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, draft_when: state.draft_when, draft_severity: state.draft_severity, draft_noteItem: state.draft_noteItem};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, draft_when: state.draft_when, draft_severity: state.draft_severity, draft_noteItem: state.draft_noteItem};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, entries: state.entries, draft_when: state.draft_when, draft_severity: state.draft_severity, draft_noteItem: state.draft_noteItem};
}





function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Headache Log", "HEADACHE LOG", "Track headaches by time of day", ""));
  {
      let entryCount: number = state.entries.length();
      let entryTotal: number = 0;
      for (let e: LogEntry of state.entries) { entryTotal = entryTotal + e.severity; }
      let headacheCount: number = entryCount;
      let avgSeverity: number = share(entryTotal, entryCount);
    sections.push(ui.Section("summary", "", "", [ui.MetricGroup("default", 2, [ui.NumberStat("default", "Headaches", headacheCount, "", "", 1, "", "chart", 0), ui.When(entryCount > 0, ui.NumberStat("default", "Average severity", avgSeverity, "", " /10", 1, "", "chart", 1)), ui.When(entryCount === 0, ui.Stat("default", "Average severity", "—", "", "chart"))])]));
    let rows: ui.View[] = [];
    let i: number = entryCount - 1;
    while (i >= 0 && i > entryCount - 21) {
      let e: LogEntry = state.entries[i];
      let sub: string = ui.clockToString(e.when) + " · " + "Added " + ui.clockToString(e.minute);
      rows.push(ui.ListItem("default", e.noteItem, sub, ui.formatNumber(e.severity, 0), "", 0, false, ""));
      rows.push(ui.ActionBar("end", [ui.Button("secondary", "Remove", "removeEntry", i, true)]));
      i = i - 1;
    }
    sections.push(ui.Section("content", "", "", [ui.TimeField("default", "Time", state.draft_when, "set_draft_when"), ui.TextField("default", "Severity", state.draft_severity, "set_draft_severity", "number"), ui.TextField("default", "Note", state.draft_noteItem, "set_draft_noteItem"), ui.ActionBar("end", [ui.Button("primary", "Add", "addEntry", 0, strings.trim(state.draft_noteItem) !== "")])]));
    sections.push(ui.Section("content", "", "", [ui.SectionHeader("default", "Headaches", "Newest first", ui.numberToString(entryCount)), ui.When(entryCount === 0, ui.EmptyState("default", "Nothing added yet", "Fill in the fields above and tap Add.", "", "", "list")), ui.When(entryCount > 0, ui.ListGroup("default", "", rows)), ui.When(state.removedEntries.length() > 0, ui.Snackbar("default", "Removed", "Undo", "undoRemove")), ui.Ticker("default", "undoClock", 6000 + state.entries.length() % 7, state.removedEntries.length() > 0, "expireUndo")]));
  }
